// FUNCTION ov12_02259358: matching C (pt2)
#pragma force_active on
void ov12_02259358(BattleSystem *battleSys, BattlerData *battlerData) {
    RefreshPartyStatusMessage *message = (RefreshPartyStatusMessage *)&battlerData->data[0];
    Pokemon *mon;
    int i, partyCount, ability;
    u32 clearedStatus = 0;
    partyCount = BattleSystem_GetPartySize(battleSys, battlerData->battler);

    for (i = 0; i < partyCount; i++) {
        mon = BattleSystem_GetPartyMon(battleSys, battlerData->battler, i);

        if (message->ability == ABILITY_MOLD_BREAKER_PT) {
            ability = ABILITY_NONE_PT;
        } else {
            ability = GetMonData(mon, MON_DATA_ABILITY_PT, ((void *)0));
        }

        if (message->move != MOVE_HEAL_BELL_PT || (message->move == MOVE_HEAL_BELL_PT && ability != ABILITY_SOUNDPROOF_PT)) {
            SetMonData(mon, MON_DATA_STATUS_PT, (u8 *)&clearedStatus);
        }
    }

    BattleController_EmitClearCommand(battleSys, battlerData->battler, message->command);
    ov12_02259928(battlerData);
}
